pub mod model{pub use mip_codex::model::*;}
#[path="support/cover_vertex_penalty/mod.rs"]mod profile;
fn main(){let a:Vec<_>=std::env::args().collect();assert!(a.len()==7||a.len()==8);let m=mip_codex::mps::read(&a[1]).unwrap();let seconds:f64=a[2].parse().unwrap();let pd:usize=a[3].parse().unwrap();let rng:u64=a[4].parse().unwrap();let steps:usize=a[5].parse().unwrap();let seed=if a.len()==8{let r:serde_json::Value=serde_json::from_slice(&std::fs::read(&a[7]).unwrap()).unwrap();Some(m.variables.iter().map(|v|r["values"][&v.name].as_f64().unwrap()).collect::<Vec<_>>())}else{None};let r=profile::diagnostic(&m,seconds,pd,seed.as_deref(),rng,steps);std::fs::write(&a[6],serde_json::to_vec_pretty(&r).unwrap()).unwrap();println!("{}",serde_json::json!({"objective":r["objective"],"stats":r["stats"],"component_seconds":r["component_seconds"],"base_source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT}));}
